pub fn diag_val(i: usize, j: usize) -> f64 {
    if i == j {
        1.0
    } else {
        0.0
    }
}

pub fn identity(n: usize) -> Vec<Vec<f64>> {
    let mut matrix: Vec<Vec<f64>> = Vec::with_capacity(n);
    for i in 0..n {
        let mut row: Vec<f64> = Vec::with_capacity(n);
        for j in 0..n {
            row.push(diag_val(i, j));
        }
        matrix.push(row);
    }
    matrix
}

